sketches.source:
setcpm(60/4)

// A ballad in Eb: Ebmaj7, Cm7, Fm7, Bb7
// From about 1 to 30 ms the piano stays on the leading side but grows wider each bar
piano: note("<[eb3 g3 bb3 d4 g4 d4 bb3 g3] [c3 eb3 g3 bb3 eb4 bb3 g3 eb3] [f3 ab3 c4 eb4 ab4 eb4 c4 ab3] [bb2 d3 f3 ab3 d4 ab3 f3 d3]>")
  .s("triangle").timbre("soft").attack(.005).decay(1).sustain(.1).release(1.2)
  .itd("<1 8 15 25>").room(.5).gain(.26)

// The tenor sax stands in the middle with no delay at all
tenor: note("<[g4@3 f4 eb4@4] [eb4@2 g4 bb4 c5@4] [ab4@3 g4 f4@2 eb4 c4] [d4@6 ~@2]>")
  .s("sawtooth").timbre("reed").vowel("o").lpf(1800).mono(1).glide(.06)
  .vib(4.5).vibdepth(.15).attack(.08).sustain(.7).release(.6).room(.5).gain(.24)

// Under about 0.7 ms the delay moves a sound sideways: the brushes sway from ear to ear
brushes: s("pink*8").hpf(2500).decay(.1).sustain(0).swing(4)
  .itd(sine.range(-.6, .6).slow(2)).gain(.05)

// A soft, centred bass
bass: note("<eb2 c2 f2 bb1>").s("sine").attack(.05).decay(.8).sustain(.4).release(.6).gain(.4)

setcpm(96/4)

// A centred walking bass and kick: Dm7, G7, Cmaj7, A7
bass: note("<[d2 f2 a2 c3] [g1 b1 d2 f2] [c2 e2 g2 b2] [a1 c#2 e2 g2]>")
  .s("sine").shape(.15).decay(.3).sustain(.3).release(.1).gain(.46)
kick: s("bd*4").lpf(200).gain(.26)
ride: s("rd [rd@2 rd] rd [rd@2 rd]").gain(.18)

// The brushes: the same noise in both ears, but one ear is phase-shifted in a narrow band
// Neither ear alone hears a tone; together they hear the chord tones
ghost: s("[~ white]*4").dichotic("<[349 440 523 440] [349 494 587 494] [330 392 494 392] [277 330 392 330]>")
  .dichoticq(30).attack(.005).sustain(1).release(.05).gain(.14)

// A quiet hint: the first bar on a vibraphone, once every four bars
hint: note("<[~ f4 ~ a4 ~ c5 ~ a4] ~ ~ ~>").s("sine").fm(2).fmh(4)
  .decay(.3).sustain(0).release(.4).gain(.08)
